// W7 - NEW slop-scan rules (same shape as RULES / SECOND_ORDER in slop-scan.mjs).
// Hebrew word edges: JS \b is ASCII-only, so Hebrew rules use lookarounds + optional proclitics.
const HB = '(?<![\\u0590-\\u05FF])';          // Hebrew word start
const HE = '(?![\\u0590-\\u05FF])';           // Hebrew word end
const P = '[ובלמהשכ]{0,3}';                    // optional proclitics ו/ב/ל/מ/ה/ש/כ
const he = (src, flags = 'g') => new RegExp(src.replaceAll('<B>', HB).replaceAll('<E>', HE).replaceAll('<P>', P), flags);
const LEGAL_PATH = /(terms|privacy|accessibility|legal|cookies|takanon|תקנון|פרטיות|נגישות)/i;
const CONTENT_PATH = /(blog|posts?\b|articles?|docs?\b|guides?|news|מדריכ|מאמר)/i;

